"""Decode JSON text returned inside HSF result envelopes without logging it."""
import json


def decode_response(value):
    # Some gateways serialize result a second time. Bound repeated decoding.
    for _ in range(3):
        if not isinstance(value, str):
            break
        try:
            value = json.loads(value)
        except (ValueError, RecursionError):
            break
    return value
